import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Navbar from '../components/Navbar';
import InternshipCard from '../components/InternshipCard';
import { searchInternships, getSavedInternships } from '../services/api';
import { useAuth } from '../context/AuthContext';

const CATEGORIES = ['All','Technology','Marketing','Design','Finance','Operations','HR','Sales','Legal'];

export default function Dashboard() {
  const { user } = useAuth();
  const location = useLocation();
  const params = new URLSearchParams(location.search);

  const [internships, setInternships] = useState([]);
  const [savedIds, setSavedIds] = useState([]);
  const [loading, setLoading] = useState(true);
  const [keyword, setKeyword] = useState(params.get('keyword') || '');
  const [locationFilter, setLocationFilter] = useState('');
  const [category, setCategory] = useState(params.get('category') || 'All');
  const [minStipend, setMinStipend] = useState('');
  const [remoteOnly, setRemoteOnly] = useState(false);

  useEffect(() => { loadSaved(); }, []);
  useEffect(() => { doSearch(); }, [category]);

  const loadSaved = async () => {
    try {
      const r = await getSavedInternships(user.email);
      setSavedIds(r.data.map(i => String(i.id)));
    } catch {}
  };

  const doSearch = async () => {
    setLoading(true);
    try {
      const r = await searchInternships({
        keyword: keyword || null,
        location: locationFilter || null,
        category: category === 'All' ? null : category,
        minStipend: minStipend || null,
      });
      let results = r.data;
      if (remoteOnly) results = results.filter(i => i.remote);
      setInternships(results);
    } catch {}
    finally { setLoading(false); }
  };

  const handleBookmarkChange = (id) => {
    setSavedIds(prev =>
      prev.includes(String(id)) ? prev.filter(x => x !== String(id)) : [...prev, String(id)]
    );
  };

  return (
    <>
      <Navbar />
      <div className="page">
        {/* Category tabs */}
        <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '8px', marginBottom: '1.5rem' }}>
          {CATEGORIES.map(c => (
            <button key={c}
              onClick={() => setCategory(c)}
              style={{
                whiteSpace: 'nowrap', padding: '7px 18px', borderRadius: '20px',
                border: '1px solid', cursor: 'pointer', fontSize: '0.85rem', fontWeight: '500',
                background: category === c ? 'var(--accent)' : 'var(--surface)',
                borderColor: category === c ? 'var(--accent)' : 'var(--border)',
                color: category === c ? 'white' : 'var(--text2)',
                transition: 'all 0.2s',
              }}>
              {c}
            </button>
          ))}
        </div>

        {/* Search & filter bar */}
        <div className="filter-bar">
          <input className="form-control" placeholder="🔍 Search by role or company…"
            value={keyword} onChange={e => setKeyword(e.target.value)}
            onKeyDown={e => e.key === 'Enter' && doSearch()} />
          <input className="form-control" placeholder="📍 Location"
            value={locationFilter} onChange={e => setLocationFilter(e.target.value)} style={{ flex: '0.5' }} />
          <select className="form-control" value={minStipend} onChange={e => setMinStipend(e.target.value)} style={{ flex: '0.5' }}>
            <option value="">💰 Any stipend</option>
            <option value="5000">₹5,000+</option>
            <option value="10000">₹10,000+</option>
            <option value="20000">₹20,000+</option>
            <option value="30000">₹30,000+</option>
          </select>
          <label style={{ display: 'flex', alignItems: 'center', gap: '6px', color: 'var(--text2)', fontSize: '0.88rem', cursor: 'pointer', whiteSpace: 'nowrap' }}>
            <input type="checkbox" checked={remoteOnly} onChange={e => setRemoteOnly(e.target.checked)} />
            Remote only
          </label>
          <button className="btn btn-primary btn-sm" onClick={doSearch}>Search</button>
        </div>

        {/* Results */}
        {loading ? (
          <div className="grid-3">
            {[...Array(6)].map((_, i) => (
              <div key={i} className="skeleton" style={{ height: '220px', borderRadius: '14px' }} />
            ))}
          </div>
        ) : internships.length === 0 ? (
          <div className="empty-state">
            <div className="icon">🔎</div>
            <p>No internships found. Try different filters.</p>
          </div>
        ) : (
          <>
            <p style={{ color: 'var(--text2)', fontSize: '0.85rem', marginBottom: '1rem' }}>
              {internships.length} internship{internships.length !== 1 ? 's' : ''} found
            </p>
            <div className="grid-3">
              {internships.map(i => (
                <InternshipCard key={i.id} internship={i} savedIds={savedIds}
                  onBookmarkChange={handleBookmarkChange} />
              ))}
            </div>
          </>
        )}
      </div>
    </>
  );
}
